package httpcaddyfile

import (
	"strings"
	"testing"

	"github.com/caddyserver/caddy/v2/caddyconfig/caddyfile"
)

func adapt(t *testing.T, name, input string) string {
	t.Helper()
	cfg, _, err := Adapter{}.Adapt([]byte(input), nil)
	if err != nil {
		t.Fatalf("%s: adapt error: %v", name, err)
	}
	return string(cfg)
}

func TestZZNestedImportInHandler(t *testing.T) {
	cfg := adapt(t, "nested", \`(responderWithStatus) {
	respond {args[0]} {args[1]}
}

(responder) {
	import responderWithStatus {args[0]} 202
}

http://127.0.0.1:8080 {
	handle {
		import responder "foobar"
	}
}
\`)
	if !strings.Contains(cfg, "\\"foobar\\"") || !strings.Contains(cfg, "202") {
		t.Fatalf("unexpected config: %s", cfg)
	}
}

func TestZZImportAtSiteLevel(t *testing.T) {
	cfg := adapt(t, "site", \`(snip) {
	respond "ok" 200
}

http://127.0.0.1:8081 {
	import snip
}
\`)
	if !strings.Contains(cfg, "\\"ok\\"") {
		t.Fatalf("unexpected config: %s", cfg)
	}
}

func TestZZDoubleExpansionOfSameSnippet(t *testing.T) {
	cfg := adapt(t, "twice", \`(snip) {
	respond {args[0]} 200
}

http://127.0.0.1:8082 {
	handle /a* {
		import snip "a"
	}
	handle /b* {
		import snip "b"
	}
}
\`)
	if !strings.Contains(cfg, "\\"a\\"") || !strings.Contains(cfg, "\\"b\\"") {
		t.Fatalf("unexpected config: %s", cfg)
	}
}

func TestZZFileImportInBlock(t *testing.T) {
	cfg := adapt(t, "file", \`http://127.0.0.1:8083 {
	handle {
		import ./testdata/import_variadic.txt
	}
}
\`)
	_ = cfg
}
EOF
